def IsWalk (G : V → V → Prop) (s t : V) (p : List V) : Prop :=
  p.head? = some s ∧ p.getLast? = some t ∧
  ∀ e ∈ p.zip p.tail, G e.1 e.2

noncomputable def distance (G : V → V → Prop) (w : V → V → ℝ≥0∞)
    (s t : V) : ℝ≥0∞ :=
  sInf {c | ∃ p, IsWalk G s t p ∧ c = cost w p}
